import{_ as i,o as a,c as n,aj as e}from"./chunks/framework.BdtAaXf2.js";const t="/assets/image-20260709165450927.CK5_8i0M.png",l="/assets/swarm-ui.CVmlOhRw.png",p="/assets/arch-overview.FFbX4X3j.svg",h="/assets/dag-dependency.Gieo0Vrf.svg",r="/assets/role-division.Cy1KZQuC.svg",k="/assets/symphony-dual-core.C7gRN1-j.svg",d="/assets/security-matrix.D2XpvpsI.svg",o="/assets/dashboard.khB41yAu.png",E="/assets/roadmap.S2X7MoTQ.svg",_=JSON.parse('{"title":"智能制造产线协作：设备依赖编排 + 角色分工 + 异构通信安全","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/jiuwenswarm-垂直行业技术文章/01-智能制造产线协作/智能制造产线协作：设备依赖编排+角色分工+异构通信安全.md","filePath":"AI人工智能/jiuwenswarm-垂直行业技术文章/01-智能制造产线协作/智能制造产线协作：设备依赖编排+角色分工+异构通信安全.md","lastUpdated":1783609931000,"__rawMarkdown":"# 智能制造产线协作：设备依赖编排 + 角色分工 + 异构通信安全\\n\\n> 当一条产线上同时存在 OPC-UA 的机械臂、MTConnect 的 CNC、MQTT 的 AGV、gRPC 的视觉相机，甚至还要和“供应商的 Agent”打交道时，谁来把这些异构设备“编排”成一支能自己跑的团队？本文以 **JiuwenSwarm** 最新蜂群（Swarm）能力为底座，拆解三个关键能力在制造场景里的落地：**设备依赖编排（Swarmflow）**、**角色分工（Agent Team）**、**异构通信安全（A2A + 分层权限策略）**。\\n\\n## 目录\\n\\n- [产线协作的三道老难题](#产线协作的三道老难题)\\n- [JiuwenSwarm 凭什么能“编排产线”](#jiuwenswarm-凭什么能编排产线)\\n- [产线协作全景](#产线协作全景)\\n- [让设备依赖自己跑起来](#让设备依赖自己跑起来)\\n  - [Swarmflow 是一段可执行的 Python](#swarmflow-是一段可执行的-python)\\n- [Agent Team 怎么分工](#agent-team-怎么分工)\\n  - [产线经验自动沉淀](#产线经验自动沉淀)\\n  - [真实的团队配置](#真实的团队配置)\\n- [几十个技能怎么选、怎么串](#几十个技能怎么选怎么串)\\n  - [一个机械臂控制技能长什么样](#一个机械臂控制技能长什么样)\\n- [异构设备怎么安全地说话](#异构设备怎么安全地说话)\\n  - [让本厂和供应商 Agent 说同一种话](#让本厂和供应商-agent-说同一种话)\\n  - [每一步都在掌控中](#每一步都在掌控中)\\n  - [真实的权限配置与内置规则](#真实的权限配置与内置规则)\\n- [一张大屏看全链路](#一张大屏看全链路)\\n- [跨机器部署产线 Agent](#跨机器部署产线-agent)\\n- [落地建议与总结](#落地建议与总结)\\n- [相关引用](#相关引用)\\n\\n---\\n\\n## 产线协作的三道老难题\\n\\n![](assets/image-20260709165450927.png)\\n\\n把一条真实产线“数字化协作”起来，传统方案几乎都会撞上三堵墙：\\n\\n| 难题 | 典型表现 | 传统解法的痛点 |\\n| --- | --- | --- |\\n| **① 设备依赖编排** | “取料没完成，CNC 不能开工；质检没过，不能入库”——任务之间有严格的先后 / 并行 / 条件依赖 | 写死在 MES 的状态机里，需求一变就要改代码、停线升级 |\\n| **② 角色分工** | 机械臂、CNC、AGV、相机各有专长，一个“大而全”的程序既难维护又容易出错 | 单体脚本，谁出了问题难定位，扩展新设备要重写 |\\n| **③ 异构通信安全** | 设备协议五花八门（OPC-UA / MTConnect / MQTT / gRPC / EtherCAT），还要连外部供应商系统 | 协议适配堆叠如山；更要命的是“谁能让机械臂动起来”缺乏统一管控 |\\n\\nJiuwenSwarm 给出的答案是：**把这些设备变成一支“Agent 团队”**，用自然语言下达产线目标，由 Leader 自动拆解、分配、推进，全程在统一的安全策略下执行。\\n\\n---\\n\\n## JiuwenSwarm 凭什么能“编排产线”\\n\\n**JiuwenSwarm** 是一款让多智能体真正协作起来的 Agent 系统，面向需要自动化处理复杂任务的开发者和团队，帮助用户通过自然语言驱动多 Agent 协作、Skill 自演进和工具调用，实现从意图到结果的端到端交付。\\n\\n它和“再写一个 RPA / 再写一个调度脚本”的根本区别在于下面这几项**最新特性**，本文将逐一把它们映射到制造场景：\\n\\n- **分布式 Agent Swarm**：Leader / Teammate 可跨进程、跨机器部署，突破单机算力瓶颈。\\n- **Swarmflow（蜂群流）**：用自然语言驱动工作流编排，Leader 自动把目标拆成多阶段工作流，各阶段 Agent 自动衔接。\\n- **Symphony（技能交响乐）**：面对几十上百个 Skill，“检索用树、编排用图”双核架构，自动选出并串成可执行的技能链。\\n- **A2A 协议**：Agent-to-Agent 通信标准，让本厂 Agent 与外部供应商 Agent 异构互通。\\n- **工具权限与安全防护**：`allow / ask / deny` 三级动作 + 分层策略，敏感动作必须人工审批。\\n\\n> 一句话理解：JiuwenSwarm 不是“再写一个调度引擎”，而是把产线协作从 **“写死的代码”** 变成 **“可对话、可演进、可审计的 Agent 团队”**。\\n\\n切到**集群模式**后，运行界面长这样——左侧是 Leader 对用户产线目标的拆解（Swarmflow DAG 可视化），下方展开的「团队成员」面板里能看到每个 Teammate 的认领、工具调用、权限审批、汇报全过程：\\n\\n![JiuwenSwarm 集群模式（Agent Team）运行界面](./assets/swarm-ui.png)\\n\\n---\\n\\n## 产线协作全景\\n\\n我们先看全貌。下图把一条“电机壳体产线”映射成了三层架构：\\n\\n![JiuwenSwarm 产线协作总体架构](./assets/arch-overview.svg)\\n\\n- **顶层 · 蜂群协作层（Agent Team）**：一个 Leader（产线调度官）+ 多个专业 Teammate（机械臂 / CNC / AGV / 视觉质检 / 供应商协同 Agent），由 Swarmflow 编排，沉淀团队记忆。\\n- **中层 · 异构通信适配层（Gateway A2A Channel）**：屏蔽设备协议差异，统一收发消息（E2A 内层协议），并在出口处做权限 / 审批拦截。\\n- **底层 · 物理产线层**：各种异构设备 + 外部供应商 Agent（通过 A2A 接入）。\\n\\n注意图里两条线的语义不同：\\n\\n- **Leader → Teammate** 的实线：是任务下发、结果汇报的**控制流**（事件驱动，自动推进）。\\n- **Teammate → A2A 适配层** 的虚线：是每个 Agent 通过自己的 **Skill** 去操作真实设备的**数据流**（双向协议适配）。\\n\\n---\\n\\n## 让设备依赖自己跑起来\\n\\n产线上最常见的诉求其实是一句话：“**把这批电机壳体加工完并质检入库**”。但这句话背后藏着一个 DAG（有向无环图）：\\n\\n> 启动 →（物料到货校验 ‖ 夹具就位 ‖ 机械臂取料）→ CNC 加工 → 视觉质检 →（人工复核？）→ AGV 入库\\n\\nJiuwenSwarm 的 **Swarmflow** 做的事，就是把这句自然语言**自动拆成上面这个 DAG**，并让各阶段 Agent 自动衔接。下图标出了一个真实批次的依赖图：\\n\\n![设备依赖编排 DAG 示例](./assets/dag-dependency.svg)\\n\\n几个关键点值得在制造场景里特别强调：\\n\\n1. **并行 + 串行混合**：T1（物料）、T2（夹具）、T3（取料）可以并行启动；T4（CNC 加工）必须等 T2、T3 都完成。Swarmflow 会自动判断“前置任务是否就绪”，而不是写死时序。\\n2. **条件分支 + 人工算子（Roadmap 中的有状态算子）**：T5（视觉质检）判定“疑似不良”时，不会盲目继续，而是进入 **H1 人工复核**节点——人作为“有状态算子”参与流程，根据中间结果审批、修正或接管后续步骤。复核通过则继续 T6 入库，复核拒绝则 Leader 重派 T4。\\n3. **事件驱动持续推进**：不是“分完工就结束”。T4 完成 → 自动触发 T5；T5 完成 → 自动判断走哪条分支。整个过程用户可观察、可介入。\\n\\n### Swarmflow 是一段可执行的 Python\\n\\n很多人以为 Swarmflow 只是“Leader 在脑子里规划”，其实不是——Swarmflow 提供了一组**可执行的工作流原语**，产线 DAG 是一段真实的 Python 代码。下面是仓库里 [SwarmSkill 工作流模板 `workflow.py.template`](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/jiuwenswarm/resources/agent/workspace/skills/swarmskill-creator/templates/scripts/workflow.py.template) 的真实结构，改成“电机壳体装配”产线后：\\n\\n```python\\nfrom swarmflow import agent, compact, log, map_parallel, parallel, phase\\n\\nMETA = {\\n    \\"name\\": \\"motor-housing-line\\",\\n    \\"description\\": \\"电机壳体产线：取料→加工→质检→入库（含人工复核分支）\\",\\n    \\"whenToUse\\": \\"当用户要求生产/加工电机壳体批次时复用此工作流\\",\\n    \\"phases\\": [\\n        {\\"title\\": \\"备料\\",   \\"detail\\": \\"物料到货校验 + 夹具就位 + 机械臂取料（并行）\\"},\\n        {\\"title\\": \\"加工\\",   \\"detail\\": \\"CNC 加工，依赖夹具与取料完成\\"},\\n        {\\"title\\": \\"质检\\",   \\"detail\\": \\"视觉质检，疑似不良触发人工复核\\"},\\n        {\\"title\\": \\"入库\\",   \\"detail\\": \\"复核通过后 AGV 入库\\"},\\n    ],\\n}\\n\\nROLE_RESULT_SCHEMA = {                       # 每个 agent() 的结构化输出\\n    \\"type\\": \\"object\\",\\n    \\"properties\\": {\\"result\\": {\\"type\\": \\"string\\"}, \\"verdict\\": {\\"type\\": \\"string\\"}},\\n}\\n\\nasync def run(args):\\n    # —— 阶段1 备料：三件事并行启动 ——\\n    phase(\\"备料\\")\\n    log(\\"并行启动：物料校验 / 夹具就位 / 机械臂取料\\")\\n    prep = await parallel([\\n        lambda: agent(build_prompt(\\"物料校验\\", args), label=\\"物料\\",  phase=\\"备料\\", schema=ROLE_RESULT_SCHEMA),\\n        lambda: agent(build_prompt(\\"夹具就位\\", args), label=\\"夹具\\",  phase=\\"备料\\", schema=ROLE_RESULT_SCHEMA),\\n        lambda: agent(build_prompt(\\"机械臂取料\\", args), label=\\"取料\\", phase=\\"备料\\", schema=ROLE_RESULT_SCHEMA),\\n    ])\\n    prep = compact(prep)                      # 容错：某分支失败时过滤掉 None\\n\\n    # —— 阶段2 加工：必须等夹具+取料都完成 ——\\n    phase(\\"加工\\")\\n    machined = await agent(\\n        build_prompt(\\"CNC加工\\", {**args, \\"prep\\": prep}),\\n        label=\\"加工\\", phase=\\"加工\\", schema=ROLE_RESULT_SCHEMA,\\n    )\\n\\n    # —— 阶段3 质检：条件分支 ——\\n    phase(\\"质检\\")\\n    qc = await agent(build_prompt(\\"视觉质检\\", machined), label=\\"质检\\", phase=\\"质检\\", schema=ROLE_RESULT_SCHEMA)\\n    if extract_json(qc).get(\\"verdict\\") == \\"疑似不良\\":\\n        log(\\"质检判定疑似不良 → 进入人工复核算子\\")\\n        review = await agent(build_prompt(\\"人工复核\\", qc), label=\\"复核\\", phase=\\"质检\\", schema=ROLE_RESULT_SCHEMA)\\n        if extract_json(review).get(\\"verdict\\") != \\"通过\\":\\n            return {\\"status\\": \\"degraded\\", \\"reason\\": \\"复核未通过，需重派加工\\"}\\n\\n    # —— 阶段4 入库 ——\\n    phase(\\"入库\\")\\n    await agent(build_prompt(\\"AGV入库\\", args), label=\\"入库\\", phase=\\"入库\\", schema=ROLE_RESULT_SCHEMA)\\n    return {\\"status\\": \\"complete\\", \\"batch\\": args.get(\\"batch_id\\")}\\n```\\n\\n这段代码里用到的原语，全部来自 `swarmflow` 模块（仓库模板的约束清单里明确列出了支持集合）：\\n\\n| 原语 | 语义 | 产线对应 |\\n| --- | --- | --- |\\n| `phase(\\"...\\")` | 稳定的**阶段标记**，必须与 `META[\\"phases\\"]` 里的 title 一一对应 | 备料 / 加工 / 质检 / 入库 |\\n| `parallel([...])` | **屏障式并行**：等所有分支都回来再继续（适合“都需要才能下一步”） | 备料阶段三件事并行 |\\n| `map_parallel(items, fn)` | **同构扇出**：对一批同质任务并行 | 一批壳体同时取料 |\\n| `pipeline(items, s1, s2)` | **每件物品有序多阶段** | 逐件：取料→加工→质检 |\\n| `agent(prompt, label, phase, schema)` | 派一个子 Agent 执行，结构化输出 | 每个设备动作 |\\n| `compact([...])` / `extract_json(...)` | **容错**：过滤失败的分支、解析 LLM 输出 | 某台设备超时不阻断整线 |\\n\\n工作流跑起来后，会持续吐出进度事件。仓库里 [`workflow_state.py`](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/jiuwenswarm/agents/harness/team/handlers/workflow_state.py) 的 `WorkflowRunState` 就是消费这些事件的状态机，它的派发表就是真实的事件流：\\n\\n```python\\n_KIND_HANDLERS = {\\n    \\"workflow_started\\":  \\"_on_workflow_started\\",\\n    \\"phase\\":             \\"_on_phase\\",          # 进入新阶段（备料→加工）\\n    \\"agent_started\\":     \\"_on_agent_started\\",  # 某设备 Agent 开始\\n    \\"agent_completed\\":   \\"_on_agent_completed\\",# 某设备 Agent 完成\\n    \\"agent_failed\\":      \\"_on_agent_failed\\",   # 某设备 Agent 失败\\n    \\"workflow_completed\\":\\"_on_workflow_completed\\",\\n    \\"workflow_failed\\":   \\"_on_workflow_failed\\",\\n    \\"log\\":               \\"_on_log\\",\\n}\\n```\\n\\n完整的生命周期是：`workflow_started → phase → agent_started → agent_completed/failed → … → workflow_completed/failed`。前端大屏上看到的“T4 加工 68%”进度条，就是这条事件流实时驱动的。\\n\\n> 这意味着：过去要改 MES 状态机、停线升级才能调整的工艺流程，现在可以通过**一段 Python 工作流**（或一句自然语言让 Leader 生成它）重新编排，**产线的“柔性”第一次真正落到可执行的代码层**。\\n\\n---\\n\\n## Agent Team 怎么分工\\n\\n有了 DAG，还需要有人去“干每个节点”。Agent Team 的思路是 **“让多个专业化的 Agent 组成团队，每个 Agent 负责自己擅长的部分”**，而不是用一个“大而全”的程序包打天下。\\n\\n![Agent Team 角色分工](./assets/role-division.svg)\\n\\n**Leader（产线调度官）的职责**：目标理解、团队组建、DAG 编排、关键决策（如审批高危动作）、整体推进、**在每个 round 结束后自动提取团队记忆**。\\n\\n**Teammate（专业执行者）的职责**：认领任务 → 独立执行 → 困难时求助 Leader → 汇报结果 → 提交中间产物。\\n\\n### 产线经验自动沉淀\\n\\n制造场景有一个刚需：**经验必须能沉淀**（哪台 CNC 在什么转速下振动大、AGV 几点该返航充电）。Agent Team 提供了双层记忆：\\n\\n| 层级 | 访问权限 | 写入方 | 产线场景含义 |\\n| --- | --- | --- | --- |\\n| **个人记忆** | 该成员独占 | 成员自身 | 机械臂 Agent 记住自己各关节的零位偏移 |\\n| **团队记忆 `TEAM_MEMORY.md`** | 所有成员只读 | Leader 在 round 结束后由提取 Agent 自动写入 | “CNC-02 主轴 >11500rpm 振动偏大，建议降速”这类跨设备经验 |\\n\\n团队记忆按 `[decision]` / `[lesson]` / `[member]` / `[context]` 分类，**跨 round 累积**——这意味着产线跑得越久，团队越“懂”这条线。\\n\\n### 真实的团队配置\\n\\n“组建团队”在 JiuwenSwarm 里不是写代码 new 一堆对象，而是声明式配置。下面是从仓库 [`config.team.distributed.leader.yaml`](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/jiuwenswarm/resources/config.team.distributed.leader.yaml) 里摘出来的真实结构（省略了无关字段），改成了产线角色：\\n\\n```yaml\\nmodes:\\n  team:\\n    jiuwen_team:                         # 团队名\\n      team_name: jiuwen_team\\n      lifecycle: persistent              # 持久团队：记忆跨 round 累积（临时团队则用 temporary）\\n      teammate_mode: build_mode\\n      spawn_mode: inprocess\\n      enable_swarmflow: true             # 开启 Swarmflow 编排（默认 true）\\n\\n      leader:\\n        member_name: team_leader\\n        display_name: 产线调度官\\n        persona: \\"资深生产调度专家，擅长产线任务分解、设备依赖编排与异常协调\\"\\n\\n      agents:                            # 每个 teammate 的运行参数\\n        leader:   { max_iterations: 200, completion_timeout: 600.0 }\\n        teammate: { max_iterations: 200, completion_timeout: 600.0 }\\n\\n      memory:\\n        enabled: true\\n        scenario: \\"general\\"              # 产线属 general 场景，用个人长期记忆\\n        auto_extract: true               # round 结束自动提取团队记忆\\n        shared_memory: true              # 写入 TEAM_MEMORY.md\\n        member_memory_prompt_mode: \\"proactive\\"\\n        timezone_offset_hours: 8.0\\n```\\n\\n关键字段对应前面的概念：\\n\\n- `lifecycle: persistent` → 触发**双层记忆**（个人记忆读写 + 团队记忆自动提取累积）；若写 `temporary` 则只读父 workspace、不留痕。\\n- `enable_swarmflow: true` → 让这个团队跑前面那套可执行工作流；关掉就退回普通多 Agent 协作。\\n- `memory.auto_extract: true` + `shared_memory: true` → 就是 Leader 在 round 结束自动写 `TEAM_MEMORY.md` 的开关。\\n\\n而真正“让团队跑起来”的入口，是 SDK 的流式执行器（仓库 [`team_helpers.py`](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/jiuwenswarm/server/runtime/agent_adapter/team_helpers.py)）：\\n\\n```python\\nasync for chunk in Runner.run_agent_team_streaming(\\n    agent_team=team_spec,            # 上面 YAML 经 load_team_spec_dict() 解析出的 TeamAgentSpec\\n    inputs={\\"query\\": initial_query}, # 用户的自然语言产线目标\\n    session=session_id,\\n    envs=envs,\\n    stream_logger=lg,\\n):\\n    ...  # 每个 chunk 是一条进度/消息事件，推给前端大屏\\n```\\n\\nLeader 收到 `initial_query` 后，会用 SDK 提供的团队工具去干活——仓库 [`code_rails.py`](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/jiuwenswarm/agents/swarm/providers/code_rails.py) 里给 Leader 注入的系统提示就点名了这些工具：\\n\\n> “Start the approved team workflow with team tools such as **build_team, create_task, spawn_teammate, and send_message**。”\\n\\n也就是说，Leader 通过 `build_team` 组队、`create_task` 建任务并指定 assignee、`spawn_teammate` 拉起成员、`send_message` 协调，**这套调用链是系统提示约束的真实工具，不是泛泛而谈**。\\n\\n> **关键认知**：Agent Team 的核心不是“更强的 Agent”，而是“**更好的协作**”。重点在于如何组织团队、分配任务、推进流程。\\n\\n---\\n\\n## 几十个技能怎么选、怎么串\\n\\n每个 Teammate 要操作真实设备，靠的是 **Skill（技能）**：机械臂 Skill 封装 OPC-UA 读写、CNC Skill 封装 MTConnect、AGV Skill 封装 MQTT……当 Skill 数量一多（几十上百个），就会撞上两个问题：**上下文被塞爆**、**模型注意力分散选错技能**。\\n\\n最新的 **Symphony（技能交响乐）** 用“双核心架构”解决：\\n\\n![Symphony 双核架构](./assets/symphony-dual-core.svg)\\n\\n- **① 技能检索（Skill Tree，怎么选）**：把平铺的技能列表组织成**可逐层浏览的技能树**，Agent 像查目录一样 `skill_branch_explore` / `skill_branch_peek`，只展开相关分支，避免把所有 `SKILL.md` 一次性塞进上下文。\\n- **② 技能编排（Skill Score，怎么用）**：基于候选技能、输入输出结构和**技能总谱**（一张描述 `can_feed` 可衔接关系的关系图），生成一条**可确认、可执行的技能链**。\\n\\n> 可以把 Symphony 理解为“双核心架构”：**检索用树，编排用图**。它判断的不只是“技能是否相关”，更是“上游输出能否真正接到下游输入”。\\n\\n**在产线上的典型链路**：取料 Skill → 加工 Skill → 测量 Skill → 质检 Skill → 入库 Skill。图里每条边的数字是**置信度**，低于 `min_edge_confidence`（默认 0.3）的边不会被优先用于编排。这样生成出来的不是“看起来相关”的技能组合，而是**能解释依赖、可确认、可执行**的技能链。\\n\\n### 一个机械臂控制技能长什么样\\n\\n很多人觉得 Symphony 很玄，那是因为没见过 Skill 的真身。一个 Skill 就是一个文件夹 + 一个 `SKILL.md`，元数据用 YAML frontmatter 声明。仓库内置技能 [`delayed-restart-app`](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/jiuwenswarm/resources/agent/workspace/skills/delayed-restart-app/SKILL.md)（重启服务）是“shell+脚本”类技能的最小范例，照它的结构写一个产线的“机械臂取放”Skill：\\n\\n```\\nopcua-arm-pickplace/\\n├── SKILL.md              # 技能定义（必需）\\n├── scripts/\\n│   └── arm_pickplace.py  # 封装 OPC-UA 读写，被 mcp_exec_command 调起\\n└── references/\\n    └── opcua-points.md   # 机械臂各关节的节点地址表\\n```\\n\\n`SKILL.md`（frontmatter 字段是机器强校验的，`name` 必须匹配 `^[a-z0-9-]+$`、`description` 禁止 `<`/`>` 字符）：\\n\\n```markdown\\n---\\nname: opcua-arm-pickplace\\ndescription: 控制产线机械臂完成取放动作。读取关节坐标、执行取料/放料、必要时急停。通过 mcp_exec_command 执行 scripts/arm_pickplace.py，经 OPC-UA 与 ABB 机械臂通信。\\nallowed_tools: [mcp_exec_command]\\n---\\n\\n# 机械臂取放控制\\n\\n## 执行方式\\n必须使用 `mcp_exec_command` 执行脚本，不要只口头回答：\\n\\n    python ~/.jiuwenswarm/agent/skills/opcua-arm-pickplace/scripts/arm_pickplace.py \\\\\\n      --host 192.168.1.11 --action pick --from A1 --to B2\\n\\n## 参数\\n- `--action`：pick（取料）/ place（放料）/ home（归位）/ estop（急停）\\n- `--from` / `--to`：料位编号\\n\\n## 边界\\n- 急停（estop）属于高危动作，会触发权限引擎 ask，需人工确认\\n- 关节坐标读取是只读，配置为 allow，无需确认\\n```\\n\\n`scripts/arm_pickplace.py`（封装 OPC-UA 的部分，用 `asyncua` 库）：\\n\\n```python\\nimport argparse, asyncio\\nfrom asyncua import Client\\n\\nasync def run(host, action, src=None, dst=None):\\n    async with Client(f\\"opc.tcp://{host}:4840\\") as client:\\n        ns = await client.get_namespace_index(\\"urn:ABB\\")\\n        joint = await client.nodes.objects.get_child([f\\"{ns}:Robot\\", f\\"{ns}:JointPos\\"])\\n        if action == \\"pick\\":\\n            await move(client, ns, src)      # 移到取料位\\n            await gripper(client, ns, True)  # 闭合夹爪\\n            await move(client, ns, dst)\\n        elif action == \\"estop\\":\\n            await client.nodes.objects.get_child([f\\"{ns}:EStop\\"]).call_method()\\n        print(f\\"{{\\\\\\"verdict\\\\\\":\\\\\\"ok\\\\\\",\\\\\\"action\\\\\\":\\\\\\"{action}\\\\\\"}}\\")  # 结构化输出喂给工作流\\n\\nif __name__ == \\"__main__\\":\\n    p = argparse.ArgumentParser()\\n    p.add_argument(\\"--host\\", required=True); p.add_argument(\\"--action\\", required=True)\\n    p.add_argument(\\"--from\\", dest=\\"src\\"); p.add_argument(\\"--to\\", dest=\\"dst\\")\\n    a = p.parse_args()\\n    asyncio.run(run(a.host, a.action, a.src, a.dst))\\n```\\n\\n**这就是“技能怎么被选、怎么被串”的全部落点**：当已安装技能很少时，模型直接看列表选；当技能多了（产线扩到几十个），开启 Symphony 后：\\n\\n1. **技能检索**把上面这种 Skill 组织进技能树（`设备控制 → 机械臂 → opcua-arm-pickplace`），Leader 用 `skill_branch_explore` 逐层找到它；\\n2. **技能编排**读技能总谱，看到 `opcua-arm-pickplace` 的输出（JSON `{verdict, action}`）能 `can_feed` 给下游的 `mtconnect-cnc`（加工 Skill），就自动生成 `取料→加工→质检` 这条链。\\n\\n仓库 frontmatter 校验器（[`validator.py`](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/jiuwenswarm/resources/agent/workspace/skills/skill-gen-4-enterprise-doc/scripts/skill_gen/validator.py)）里允许的字段就这些，超出会被硬拒：\\n\\n```python\\nALLOWED_FRONTMATTER_KEYS = {\\n    \\"name\\", \\"description\\", \\"license\\",\\n    \\"allowed-tools\\", \\"allowed_tools\\",\\n    \\"metadata\\", \\"compatibility\\",\\n}\\n```\\n\\n> 所以“Skill”不是一个营销词，它有**确定的文件结构、强校验的元数据、明确的执行入口（bash/mcp_exec_command 调脚本）**，Symphony 的树和图都是基于这些真实 Skill 构建出来的。\\n\\n---\\n\\n## 异构设备怎么安全地说话\\n\\n让 Agent 能“指挥”机械臂动起来，是件既强大又危险的事。JiuwenSwarm 在通信层和权限层做了两道闸。\\n\\n### 让本厂和供应商 Agent 说同一种话\\n\\n产线不仅要“对内协作”，还要“对外协同”：物料什么时候到、供应商系统能否提前预警。JiuwenSwarm 的 **A2A（Agent-to-Agent）协议** 提供了标准化的对外通道：对外暴露标准 **JSON-RPC** 入口与 **Agent Card**（`/.well-known/agent-card.json`），外部 A2A 客户端可统一发现并调用。\\n\\n这不是文档上的承诺，而是 [`a2a_connect.py`](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/jiuwenswarm/gateway/channel_manager/protocol/a2a/a2a_connect.py) 里的真实代码。启动时构造的 `AgentCard` 长这样：\\n\\n```python\\nagent_card = AgentCard(\\n    name=self.config.app_name,\\n    description=self.config.app_description,\\n    version=self.config.app_version,\\n    supported_interfaces=[\\n        AgentInterface(\\n            url=f\\"http://{self.config.host}:{self.config.port}{self.config.rpc_path}\\",\\n            protocol_binding=\\"jsonrpc\\",\\n            protocol_version=self.config.protocol_version,   # 默认 1.0.0\\n        )\\n    ],\\n    capabilities=AgentCapabilities(streaming=True, push_notifications=False),\\n    default_input_modes=[\\"text/plain\\"],\\n    default_output_modes=[\\"text/plain\\"],\\n    skills=[\\n        AgentSkill(\\n            id=\\"chat\\", name=\\"chat\\",\\n            description=\\"Send user prompt to JiuwenSwarm via Gateway\\",\\n            tags=[\\"chat\\", \\"gateway\\", \\"jiuwenswarm\\"],\\n            examples=[\\"Hello\\", \\"Summarize this\\"],\\n            input_modes=[\\"text/plain\\"], output_modes=[\\"text/plain\\"],\\n        )\\n    ],\\n)\\n```\\n\\n启用它只需在 `~/.jiuwenswarm/config/.env` 里加几个环境变量（`app_gateway.py` 启动时读取），然后装可选依赖：\\n\\n```bash\\npip install \\"jiuwenswarm[a2a]\\"          # 装的是 a2a-sdk[http-server]==1.0.0\\n```\\n\\n```ini\\n# ~/.jiuwenswarm/config/.env\\nA2A_SERVER_ENABLED=true                 # 不设默认关闭；1/true/yes/on 都算开\\nA2A_SERVER_HOST=0.0.0.0                 # 对供应商暴露用 0.0.0.0，本机调试用 127.0.0.1\\nA2A_SERVER_PORT=19100                   # 别和 Web/ACP 端口冲突\\nA2A_SERVER_PATH=/a2a                    # JSON-RPC 入口路径\\nA2A_SERVER_CARD_PATH=/.well-known/agent-card.json\\nA2A_SERVER_APP_NAME=电机壳体产线Agent\\n```\\n\\n供应商那边的 Agent 怎么调用你的产线？一个标准的 A2A JSON-RPC 调用（仓库 [《A2A 接入说明》](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/docs/zh/A2A.md) 的真实示例）：\\n\\n```bash\\n# 非流式：问“下一批物料几点到”\\ncurl -sS -X POST \\"http://产线IP:19100/a2a\\" -H \'Content-Type: application/json\' \\\\\\n  -d \'{\\"jsonrpc\\":\\"2.0\\",\\"id\\":\\"m1\\",\\"method\\":\\"SendMessage\\",\\"params\\":{\\"message\\":{\\n        \\"messageId\\":\\"req-1\\",\\"contextId\\":\\"ctx-1\\",\\"role\\":\\"ROLE_USER\\",\\n        \\"parts\\":[{\\"text\\":\\"下一批 H7 电机壳体 ETA？\\"}]}}}\'\\n\\n# 流式：边产出边收（capabilities.streaming=true 才支持）\\ncurl -sS -N -X POST \\"http://产线IP:19100/a2a\\" -H \'Content-Type: application/json\' \\\\\\n  -d \'{\\"jsonrpc\\":\\"2.0\\",\\"id\\":\\"m2\\",\\"method\\":\\"SendStreamingMessage\\",\\"params\\":{\\n        \\"message\\":{\\"messageId\\":\\"req-2\\",\\"contextId\\":\\"ctx-1\\",\\"role\\":\\"ROLE_USER\\",\\n        \\"parts\\":[{\\"text\\":\\"查询今日各工位良品率\\"}]}}}\'\\n```\\n\\n入站时 `_A2AAgentExecutor` 把 A2A 的 `message.parts` 映射成内部 `Message.params`（文本合并为 `query`、非文本落 `files[]`）；回包时把内部 `payload` 反向映射成 A2A `Part`（支持多模态 url/data/raw）。终结态映射：`CHAT_ERROR→FAILED`、`CHAT_INTERRUPT_RESULT→CANCELED`、其余→`COMPLETED`。\\n\\n> 换句话说，**供应商的 Agent 不需要懂你的 OPC-UA / MTConnect，只要会说 A2A**，就能接入你的产线协作——这正是“异构通信”在跨企业边界上的延伸。（注：当前仓库实现的是**入站 A2A Server**；出站去调外部 A2A Agent 的能力在本仓库尚未包含，跨企业双向协同时由对方作 Server。）\\n\\n### 每一步都在掌控中\\n\\n更关键的是“谁能做什么”。JiuwenSwarm 的工具权限采用 **`allow / ask / deny` 三级动作** + **分层策略（tiered_policy）**：\\n\\n![异构通信安全矩阵](./assets/security-matrix.svg)\\n\\n上半部分是 **severity × 模式** 的动作映射矩阵，并配了产线场景举例：\\n\\n| severity | normal 模式 | strict 模式 | 产线举例 |\\n| --- | --- | --- | --- |\\n| LOW（读状态） | allow | allow | 读取机械臂当前坐标 |\\n| MEDIUM（参数下发） | allow | **ask** | 下发主轴转速 12000rpm |\\n| HIGH（动作类） | **ask** | **ask** | 机械臂取放 / AGV 移动 |\\n| CRITICAL（高危） | **ask** | **deny** | 整线急停 / 修改安全围栏 |\\n\\n下半部分是 **一次工具调用如何定级**的六步流程（`evaluate_tiered_policy` 的真实分支顺序）：\\n\\n1. **整工具基线**：若某工具被设为 `deny`，立即返回拒绝，不再看任何参数规则。\\n2. **内置安全规则**（`builtin_rules.yaml`）：内置 `deny` 优先于同层其它级别——例如 `bash(re:.*rm -rf.*)` 会被直接拦下。\\n3. **用户参数规则**：用户 `deny` 在 `approval_overrides` 之前生效，可以拦住本应命中的“总是允许”。\\n4. **approval_overrides**：“总是允许”命中即 `allow`——把高频低危操作（如每次都要点确认的“读关节坐标”）持久化为 allow，省掉重复审批；但**无法绕过内置 deny**。\\n5. **external_directory**：MES 数据库、产线配方目录属于 workspace 外路径，单独走路径校验，与当前级别做 strictest 合并。\\n6. **shell_operators 升阶**：含管道 / 提权 / 远程下载的命令，即使配置了 allow 也会被升为 ask。\\n\\n### 真实的权限配置与内置规则\\n\\n上面这些不是理论，是 [`config.yaml`](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/jiuwenswarm/resources/config.yaml) 里 `permissions:` 段的真实字段（产线版精简）：\\n\\n```yaml\\npermissions:\\n  enabled: true                        # 产线务必开启；关闭后所有工具返回 allow\\n  schema: tiered_policy                # 启用分层策略\\n  permission_mode: strict              # 产线建议 strict：MEDIUM→ask, CRITICAL→deny\\n\\n  defaults:\\n    \\"*\\": \\"allow\\"                       # 未命中的兜底（strict 下仍会被 severity 覆盖）\\n\\n  tools:                               # 整工具基线\\n    bash: ask                          # 任何 shell 默认要确认\\n    mcp_exec_command: ask              # 调脚本（含我们的 OPC-UA 脚本）默认确认\\n    write_file: ask\\n    read_memory: allow                 # 读记忆/待办免确认，减少打断\\n    todo_create: allow\\n\\n  rules:                               # 参数级规则（更细粒度）\\n    - id: shell_allow_dir\\n      tools: [bash, mcp_exec_command, create_terminal]\\n      pattern: \\"dir *\\"\\n      severity: LOW                    # 只读目录 → allow\\n    - id: shell_ask_rm\\n      tools: [bash, mcp_exec_command, create_terminal]\\n      pattern: \\"rm *\\"\\n      severity: HIGH                   # 删除 → ask\\n    - id: path_ask_env\\n      tools: [read_file, write_file, grep, list_dir]\\n      pattern: \\"**/.env*\\"\\n      severity: HIGH                   # 读 .env → ask\\n\\n  external_directory:\\n    \\"*\\": \\"ask\\"                         # 访问产线配方/MES 等 workspace 外路径要确认\\n    \\"D:/产线配方/\\": allow               # 可对特定可信目录放行\\n```\\n\\n更狠的是**内置安全规则**（[`builtin_rules.yaml`](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/jiuwenswarm/resources/builtin_rules.yaml)，即使用户不配也生效，且用户无法用 override 绕过）。仓库里真实存在的高危规则（节选）：\\n\\n```yaml\\n- id: shell_fs_recursive_or_forced_delete\\n  description: \\"递归、强制或批量删除关键路径，可能造成不可恢复的数据破坏\\"\\n  tools: [bash, mcp_exec_command, create_terminal]\\n  match_type: command\\n  pattern: \'re:(?i)(rm\\\\s+[^;&|]*(-[A-Za-z]*[rR][A-Za-z]*[fF]|--recursive|--force)[^;&|]*(/|\\\\*|~))\'\\n  severity: CRITICAL                   # strict 模式下 → deny\\n\\n- id: shell_privilege_escalation\\n  description: \\"通过 sudo/su/doas/pkexec/runas 提升权限\\"\\n  pattern: \'re:(?i)(sudo|doas|pkexec)\\\\s+|su\\\\s+(-|root|\\\\w)|runas\\\\b\'\\n  severity: CRITICAL\\n\\n- id: shell_system_shutdown_or_reboot\\n  description: \\"关机、重启或切换运行级别\\"\\n  pattern: \'re:(?i)(shutdown|reboot|halt|poweroff)\\\\b|(init|telinit)\\\\s+(0|6)\\\\b\'\\n  action: deny                         # 这条直接硬拒，不分模式\\n```\\n\\n**在产线上的实际效果**：当机械臂 Agent 想执行急停、AGV Agent 的脚本里出现 `sudo`、或者有人想让 Agent 跑 `rm -rf` 清理产线日志，这些规则会**在用户配置之上先拦下**——`CRITICAL` 在 strict 模式变 `deny`，带 `action: deny` 的规则任何模式都拒。\\n\\n在 TUI 里还可以用 `/permissions` 命令实时管理（写入的就是上面 `permissions.tools` / `permissions.rules`）：\\n\\n```bash\\n# 允许读取机械臂状态（持久化到 approval_overrides）\\n/permissions allow read_state\\n\\n# 任何含 rm -rf 的命令一律拒绝（内置 deny 之上再加双保险）\\n/permissions deny bash(re:.*rm -rf.*)\\n\\n# 写产线配方前必须确认\\n/permissions ask write_file(re:.*recipe.*\\\\.yaml$)\\n```\\n\\n---\\n\\n## 一张大屏看全链路\\n\\n把上面四个能力拼到一起，运行起来是什么样？下面这张是“电机壳体产线监控大屏”：\\n\\n![产线协作监控大屏](./assets/dashboard.png)\\n\\n大屏分三栏，恰好对应本文的三大主题：\\n\\n- **左栏 · Agent Team 实时状态**：可以看到 Leader 正在“编排 T4→T5 依赖”，各 Teammate 的认领 / 执行 / 等待 / 条件分支状态一目了然；底部是当轮自动沉淀的 `TEAM_MEMORY.md`（`[lesson]` CNC 降速建议、`[decision]` 质检走 H1 复核、`[member]` AGV 返航规则）。\\n- **中栏 · 产线吞吐与节拍**：KPI（良品 / 待复核 / 不良率 / 节拍）+ 近 60 分钟产出曲线（实际 vs 计划）+ 异常事件标记；下方是当前 Swarmflow DAG 的实时进度条 `T4加工(68%) → T5质检→H1复核 → T6入库`。\\n- **右栏 · 异构设备状态 + 权限审批日志**：每台设备的协议（OPC-UA / MTConnect / MQTT / gRPC / EtherCAT）、温度 / 电量 / 负载；以及按 `allow/ask/deny` 染色的权限日志——`set_spindle(12000rpm)` 被 strict 模式升为 ask、`rm -rf` 被内置规则 deny、外部 MES 目录访问被 ask。\\n\\n> 这张屏背后没有任何“写死的调度脚本”——所有任务流转、记忆沉淀、权限判定，都由 JiuwenSwarm 的 Agent Team + Swarmflow + Symphony + 分层策略自动完成。\\n\\n---\\n\\n## 跨机器部署产线 Agent\\n\\n产线规模一大，单机肯定扛不住。JiuwenSwarm 的**分布式 Agent Swarm** 让 Leader / Teammate 可以跨进程、跨机器部署：\\n\\n- **控制面**：Teammate 启动后向 A2X 注册中心注册为“空闲节点”，Leader 组队时通过 `reserve_blank_agents` 预约，再用 direct ZMQ 发送 bootstrap 接管——Leader **不需要预先知道 Teammate 的地址**。\\n- **数据面**：任务、成员状态、消息走共享存储（推荐 PostgreSQL）；team-workspace 通过 NFS 等共享目录让成员产出的文件彼此可见。\\n- **会话语义**：分布式模式保持**单活 session**，确保远程成员的 bootstrap、传输连接和运行时资源不会跨会话复用。\\n\\nLeader 与 Teammate 的关键差异，就体现在 `team.runtime` 和 `team.transport` 两段配置上。下面是仓库 [`config.team.distributed.leader.yaml`](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/jiuwenswarm/resources/config.team.distributed.leader.yaml) / [`config.team.distributed.teammate.yaml`](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/jiuwenswarm/resources/config.team.distributed.teammate.yaml) 里的真实字段对比（省略相同部分）：\\n\\n```yaml\\n# —— Leader（中央机房）——\\nteam:\\n  runtime:\\n    mode: distributed\\n    role: leader\\n\\n  transport:\\n    type: pyzmq\\n    params:\\n      direct_addr: tcp://0.0.0.0:28555          # Leader 绑定，等 Teammate 来连\\n      pubsub_publish_addr: tcp://127.0.0.1:28556\\n      pubsub_subscribe_addr: tcp://127.0.0.1:28557\\n      metadata:\\n        pubsub_bind: true                        # Leader 绑定 pubsub\\n\\n  storage:\\n    type: postgresql\\n    params:\\n      connection_string: postgresql+asyncpg://postgres:postgres@127.0.0.1:5432/jiuwen_team\\n\\n# —— Teammate（某台产线工控机）——\\nteam:\\n  runtime:\\n    mode: distributed\\n    role: teammate\\n    member_name: teammate_1                       # 本进程默认身份\\n\\n  transport:\\n    type: pyzmq\\n    params:\\n      direct_addr: tcp://0.0.0.0:28611            # 自己的通信地址\\n      bootstrap_direct_addr: tcp://127.0.0.1:28610 # 向注册中心发布的可连接地址\\n      pubsub_publish_addr: tcp://127.0.0.1:28556   # 连 Leader 的 pub\\n      pubsub_subscribe_addr: tcp://127.0.0.1:28557\\n      # 注意 teammate 不写 pubsub_bind: true\\n```\\n\\n注意 Leader/Teammate 双方都要指向**同一个** `react.a2x_registry`（A2X 注册中心）和**同一个** `team.storage`（PostgreSQL），这是分布式协作的前提：\\n\\n```yaml\\nreact:\\n  a2x_registry:\\n    base_url: \\"http://127.0.0.1:8000\\"   # Leader 和 Teammate 必须指向同一注册中心\\n    dataset: \\"team_pool\\"\\n    # Leader 端：role: teamleader\\n    # Teammate 端：role: teammate + endpoint: \\"tcp://127.0.0.1:28610\\"（自己发布的地址）\\n```\\n\\n> Teammate 启动时由 `AsyncA2XRegistryClient.register_blank_agent(...)` 把自己注册成空闲节点；Leader 组队时调 `reserve_blank_agents` 预约、拿到 endpoint 后用 direct ZMQ 发 bootstrap 接管。`dataset` 和 `endpoint` 两者必须同时配置，否则自动注册会被跳过。\\n\\n最小启动形态（四个进程）：\\n\\n```bash\\n# 1) A2X 注册中心（独立部署，从 agent-protocol 仓装）\\na2x-registry                          # 默认 127.0.0.1:8000\\n\\n# 2) Teammate（某台产线工控机）\\nJIUWENSWARM_DATA_DIR=\\"<TEAMMATE_DATA_DIR>\\" \\\\\\nAGENT_SERVER_PORT=28193 \\\\\\npython -m jiuwenswarm.server.app_agentserver\\n\\n# 3) Leader（中央机房）\\nJIUWENSWARM_DATA_DIR=\\"<LEADER_DATA_DIR>\\" \\\\\\nAGENT_SERVER_PORT=28192 GATEWAY_PORT=29101 WEB_PORT=29100 \\\\\\npython -m jiuwenswarm.app\\n\\n# 4) Web 前端（可选）\\ncd jiuwenswarm/channels/web/frontend && npm run dev -- --host 0.0.0.0 --port 5173\\n```\\n\\n> 在制造场景里，这意味着：**每台关键设备的工控机都可以跑一个专属 Teammate Agent**，中央机房跑 Leader 统一编排，跨厂区的供应商 Agent 通过 A2A 接入——物理拓扑和协作拓扑终于可以分离了。\\n\\n---\\n\\n## 落地建议与总结\\n\\n如果你也想在自己的产线上试一把，建议按这个节奏来——四个阶段层层递进，后一阶段继承前一阶段的配置与记忆，不必推翻重来：\\n\\n![产线 Agent 化落地路线图](./assets/roadmap.svg)\\n\\n1. **先单机跑通一个“最小产线”**：1 个 Leader + 2~3 个 Teammate（比如机械臂 + CNC + 视觉），用本地模式验证 Swarmflow DAG 和团队记忆。\\n2. **用 Symphony 管理技能**：当设备 Skill 超过 20 个，开启技能检索 + 技能总谱，让编排自动选链，而不是硬编码调用顺序。\\n3. **上线前配好安全策略**：把 `permission_mode` 切到 `strict`，高危动作（动作类 / 急停 / 改安全参数）显式 `deny` 或 `ask`；用 `approval_overrides` 把高频低危操作持久化为 allow。\\n4. **需要跨厂区协同时再上分布式**：部署 A2X 注册中心 + 共享 PostgreSQL + NFS 工作区，把设备 Agent 分布到各工控机。\\n\\n### 三句话总结\\n\\n- **设备依赖编排**：Swarmflow 把自然语言目标自动拆成 DAG，并行 / 串行 / 条件分支 / 人工算子全覆盖，产线流程不再写死在 MES 里。\\n- **角色分工**：Agent Team 的 Leader/Teammate 分级自主协同 + 双层团队记忆，让产线经验越跑越沉淀。\\n- **异构通信安全**：A2A 让本厂与供应商 Agent 异构互通；`allow/ask/deny` 三级动作 + 分层策略，让“自主跑”和“关键动作人批”同时成立。\\n\\n未来，随着 AgentSwarms 在更多制造场景中的深入应用，**人机协作的产线模式将成为提升制造效率与柔性的关键杠杆**——而 JiuwenSwarm 正在把这条路铺平。\\n\\n---\\n\\n## 相关引用\\n\\n1. JiuwenSwarm 官网：<https://openjiuwen.com>\\n2. JiuwenSwarm 仓库（GitCode）：<https://gitcode.com/openJiuwen/jiuwenswarm>\\n3. 官方文档：\\n   - [Agent Team 使用指南](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/docs/zh/AgentTeam.md)\\n   - [Symphony：技能编排与智能分发](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/docs/zh/Symphony-技能编排与分发.md)\\n   - [A2A 接入说明](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/docs/zh/A2A.md)\\n   - [工具权限与安全防护](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/docs/zh/工具权限与安全防护.md)\\n   - [分布式 Team](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/docs/zh/分布式Team.md)\\n4. Swarm Skills Hub：<https://swarmskills.openjiuwen.com/>\\n"}'),g={name:"AI人工智能/jiuwenswarm-垂直行业技术文章/01-智能制造产线协作/智能制造产线协作：设备依赖编排+角色分工+异构通信安全.md"};function c(m,s,y,u,F,b){return a(),n("div",null,[...s[0]||(s[0]=[e("",142)])])}const C=i(g,[["render",c]]);export{_ as __pageData,C as default};
